/**
 * Thrown when a create-owner request is missing or blank in one or more required fields.
 * Handled globally by {@link OwnerFieldsInvalidExceptionHandler}, which responds 400 with a
 * JSON body whose {@code errors} array lists the offending field names.
 */
public class OwnerFieldsInvalidException extends Exception {

    private final List<String> errors;

    public OwnerFieldsInvalidException(List<String> errors) {
        super("Missing or blank required fields: " + errors);
        this.errors = List.copyOf(errors);
    }

    public List<String> getErrors() {
        return this.errors;
    }
}

